INSERT OR IGNORE INTO realisations (room, finish, title_fr, title_nl, title_en, desc_fr, desc_nl, desc_en, published, sort, legacy_id, created_by) VALUES ('cuisine', 'noyer', 'Cuisine en noyer & îlot noir', 'Keuken in noten met zwart eiland', 'Walnut kitchen with black island', 'Un contraste élégant entre le noyer chaleureux et l''îlot noir. La tablette repas en chêne prolonge naturellement l''ensemble, avec des façades sans poignée pour une ligne épurée.', 'Zwart werkblad, eiken eettablet dat het eiland verlengt, greeploze fronten.', 'Black worktop, oak breakfast ledge extending the island, handleless fronts.', 1, 71, 'cuisine-noyer-ilot-noir', 'import');
INSERT INTO realisation_photos (realisation_id, src, width, height, position) SELECT id, '/photos/cuisine-noyer-ilot-noir.webp', 2400, 1800, 0 FROM realisations WHERE legacy_id = 'cuisine-noyer-ilot-noir' AND NOT EXISTS (SELECT 1 FROM realisation_photos WHERE src = '/photos/cuisine-noyer-ilot-noir.webp');
INSERT OR IGNORE INTO realisations (room, finish, title_fr, title_nl, title_en, desc_fr, desc_nl, desc_en, published, sort, legacy_id, created_by) VALUES ('cuisine', 'noyer', 'Cuisine en noyer, niche éclairée', 'Noten keuken met verlichte nis', 'Walnut kitchen with lit recess', 'Un placage noyer continu qui enveloppe la cuisine, associé à une niche en pierre et une hotte parfaitement intégrée.', 'Doorlopend notenfineer, nis in steen, ingebouwde dampkap.', 'Continuous walnut veneer, stone-lined recess, integrated extractor.', 1, 70, 'cuisine-noyer-hotte', 'import');
INSERT INTO realisation_photos (realisation_id, src, width, height, position) SELECT id, '/photos/cuisine-noyer-hotte.webp', 2400, 1800, 0 FROM realisations WHERE legacy_id = 'cuisine-noyer-hotte' AND NOT EXISTS (SELECT 1 FROM realisation_photos WHERE src = '/photos/cuisine-noyer-hotte.webp');
INSERT OR IGNORE INTO realisations (room, finish, title_fr, title_nl, title_en, desc_fr, desc_nl, desc_en, published, sort, legacy_id, created_by) VALUES ('cuisine', 'noyer', 'Îlot en marbre & noyer', 'Eiland in marmer', 'Marble island', 'Un plan en pierre aux veines continues, accompagné d''un mur de rangement en noyer pour créer un ensemble à la fois chaleureux et graphique.', 'Massief blad met de nerf doorgetrokken tot op de zijkanten, notenkastenwand.', 'Solid top with the vein carried down the sides, walnut storage wall.', 1, 69, 'cuisine-ilot-marbre', 'import');
